    [C("Inevitable abortion"), L("Heavy bleeding", "Abdominal pain", "Opened cervix", "Uterus corresponds to dates"), C("Intrauterine gestation sac ± fetal pole ± fetal activity"), L(VS, "Insert 2 large IV lines, run normal saline or Ringer's lactate, and relieve pain.", REF, "Ultrasound scan to be done at health centre or hospital.")],
    [C("Incomplete abortion"), L("Heavy bleeding with history of expulsion of products of conception", "Abdominal pain", "Uterus smaller than dates", "Opened cervix"), L("Heterogeneous tissues ± gestation sac", "Any endometrial thickness >15 mm"), L(VS, "Insert 2 large IV lines, run normal saline or Ringer's lactate, and relieve pain.", REF, "Ultrasound scan to be done at health centre or hospital.", "MVA should be done to evacuate the uterus by a trained health professional.")],
    [C("Complete abortion"), L("Bleeding and abdominal pain cease", "Cervix closed"), L("Empty uterus", "Endometrial thickness <15 mm"), C("Ultrasound scan to be done at health centre or hospital.")],
    [C("Missed abortion / early fetal demise"), L("Bleeding", "Abdominal pain, loss of pregnancy symptoms", "Closed cervix"), L("Fetal pole >7 mm with no fetal heart activity", "Mean gestation sac diameter >25 mm with no fetal pole or yolk sac"), C("Ultrasound scan to be done at health centre or hospital.")],
    [C("Molar pregnancy"), L("Heavy bleeding with history of expulsion of products of conception", "Abdominal pain", "Nausea and vomiting", "Opened cervix", "Uterus larger than dates", "Uterus softer than normal"), L("'Snowstorm' appearance of mixed echogenicity", "± Large theca lutein cysts"), C("Ultrasound scan to be done at health centre or hospital. The uterus should be evacuated by a trained health professional and the client followed up stringently as per guidelines.")],
